// <auto-generated/>
using DNAide.Data;
using DNAide.Web;
using Sunplus.Accounting.Core.Extensions;
using Sunplus.Accounting.DataAccess.IBCDLL.Customer;
using System;
using System.Data;
using System.Web.UI;

public partial class Customer_EditDirectCustomerInfo : RequiredAuthorizationPage
{
    public string CustDirectInfoTitle = "";

    protected void Page_Load(object sender, EventArgs e)
    {
        Page.Title = "Edit Information";
        if (Session["AccId"] != null)
        {
            CustDirectInfoTitle = GetCustLevelByName(Request["roleId"].ToString()) + ": " + Request["userName"].ToString();
            EditCustInfoContentHtml.Text = GenEditCustInfoContent();
        }
    }

    private string GenEditCustInfoContent()
    {
        string strHtml = string.Empty;
        try
        {
            DbResult ds = null;
            if (Request["custId"] == null) return "";
            ds = SelectCustomer.CustomerSelDirectInfo(Request["custId"]);
            if (ds != null)
            {
                DataTable tbl = ds.ResultSet.Tables[0];
                if (tbl.Rows.Count > 0)
                {
                    DataRow directCustomerInfo = tbl.Rows[0];
                    strHtml = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplateBySystem("Customer/EditDirectCustomerInfo.htm");                   
                    TemplateHandler.Assign(ref strHtml, "{PersonInCharge}", directCustomerInfo["processedby"].ToString());
                    TemplateHandler.Assign(ref strHtml, "{Boss}", directCustomerInfo["boss"].ToString());
                    TemplateHandler.Assign(ref strHtml, "{Requestor}", directCustomerInfo["requestby"].ToString());
                    TemplateHandler.Assign(ref strHtml, "{Approver}", directCustomerInfo["approvedby"].ToString());
                    TemplateHandler.Assign(ref strHtml, "{Phone}", directCustomerInfo["mobilephone"].ToString());
                    TemplateHandler.Assign(ref strHtml, "{Currency}", directCustomerInfo["currency"].ToString());
                    TemplateHandler.Assign(ref strHtml, "{MaxLoss}", IBCUtils.FormatHandler.FormatNumber20(directCustomerInfo["maxloss"]));
                    strHtml += Sunplus.Accounting.Core.Web.WebUtils.LoadHtml("Hidden.htm", new string[] { "{name}", "{strValue}" }, new string[] { "custId", Request["custId"] });
                }
            }
        }
        catch (Exception ex)
        {
            LogExtensions.ExceptionHandler(ex);
        }
        return strHtml;
    }
    private string GetCustLevelByName(string roleId)
    {
        switch (roleId)
        {
            case "4":
                return "Super";
            case "3":
                return "Master";
            case "2":
                return "Agent";
            default:
                return "Memebr";
        }
    }
}